import{_ as o,l as n,o as t,c as s,v as d,p as m,x as l,d as r,i as p,S as E,b as e}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"记忆化与版权","description":"","frontmatter":{"title":"记忆化与版权","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/memorization-copyright.md","filePath":"llm/memorization-copyright.md","lastUpdated":1789023840000}'),h={name:"llm/memorization-copyright.md"};function c(u,a,f,A,D,b){const i=n("Mermaid");return t(),s("div",null,[a[1]||(a[1]=d('<h1 id="记忆化与版权" tabindex="-1">记忆化与版权 <a class="header-anchor" href="#记忆化与版权" aria-label="Permalink to &quot;记忆化与版权&quot;">​</a></h1><div class="epigraph"><p>能复现训练里的长片段，是提取问题，也是版权问题。能力评测上的「答对」不能自动豁免。</p><footer>—— Carlini 等对训练数据提取的工作；对照 [成员推断](/llm/membership-extraction)</footer></div><p><a href="/llm/abstention-calibrated-refusal">上一课</a>处理不确定时不编。本课处理<strong>太确定</strong>：记忆化——生成与训练语料近乎逐字重叠。缺口不是再讲一遍去重，而是把「提取成功」从「泛化答对」里切开，并标明版权是法律问题、本栏只写技术可观测性。后课 DP-SGD 给的是训练期隐私预算，不是版权许可。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>技术观测：给定前缀，测量最长公共子串、n-gram 覆盖、相对语料的压缩比。Carlini 等人展示：较大模型、较多重复的样本、提示接近原文时，提取更容易。成员推断更弱，只猜「是否在集内」。产品侧：生成过滤器、许可语料、重复文档下调权，见 <a href="/llm/web-clean-dedup">网页去重</a>。本课不写如何最大化提取。</p><p><span class="marginnote">代码与歌词是高频提取对象，因为重复率高、用户会给第一行当提示。新闻与书籍则更多走版权争议而非「能否提取」的实验室设定。</span></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干安全课已有 <a href="/llm/membership-extraction">训练数据提取</a>。补层要接对齐：记忆化可以表现为「诚实引用」的幻觉反面——引用是真的，因为在背。评测若只奖事实正确，会奖励背诵。版权持有人关心的是复制，不是事实真值。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>重复样本降低「下一 token」在该序列上的损失，等于把语料当查找表。去重不完全消除：近重复、模板、样例代码仍会进模型。对齐 SFT 若含版权材料，会把记忆从预训练搬到对话风格里。DP 噪声（下一课）压的是个体样本影响，对「极高频重复的公共文本」效果有限。</p>',10)),(t(),m(E,null,{default:l(()=>[p(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CORP%5B%22%E8%AE%AD%E7%BB%83%E8%AF%AD%E6%96%99%22%5D%20--%3E%20MEM%5B%22%E4%BD%8E%E6%8D%9F%E5%A4%B1%E8%AE%B0%E5%BF%86%22%5D%0A%20%20MEM%20--%3E%20EXT%5B%22%E5%89%8D%E7%BC%80%E6%8F%90%E5%8F%96%22%5D%0A%20%20EXT%20--%3E%20LAW%5B%22%E5%A4%8D%E5%88%B6%20%2F%20%E7%89%88%E6%9D%83%E4%BA%89%E8%AE%AE%22%5D%0A%20%20EXT%20--%3E%20PRIV%5B%22%E9%9A%90%E7%A7%81%E6%8F%90%E5%8F%96%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"边界",tabindex:"-1"},[r("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[3]||(a[3]=e("p",null,"本课不提供法律结论，不提供提取攻击步骤。下一课 DP-SGD 是隐私工具，不能当成版权合规。开源权重上的记忆化检测仍要用持有语料，没有语料就没有金标重叠率。",-1)),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[r("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"记忆化：长片段可提取，与泛化答对不是同一指标。"),e("li",null,"版权关心复制；事实正确不自动豁免。"),e("li",null,"去重、许可、过滤是工程控制，DP 是另一条轴。"),e("li",null,"出处：Carlini 等；成员推断课。")],-1))])}const x=o(h,[["render",c]]);export{P as __pageData,x as default};
